#!/bin/sh
# Imports ops-agent-partial-import.json into the running platform realm and prints the generated client secrets to
# files under $OUT (default ./.kc-secrets, gitignore it). Nothing secret is printed to the terminal.
#
#   KC_URL=http://localhost:8190 KC_ADMIN_USER=admin KC_ADMIN_PASSWORD=... deploy/keycloak/import-ops-agent.sh
#
# Secrets are generated by Keycloak at import (the JSON carries none). Re-running skips existing resources
# (ifResourceExists SKIP) and re-reads the current secrets.
set -eu
KC_URL=${KC_URL:-http://localhost:8190}
REALM=${REALM:-platform}
OUT=${OUT:-./.kc-secrets}
HERE=$(cd "$(dirname "$0")" && pwd)
: "${KC_ADMIN_PASSWORD:?set KC_ADMIN_PASSWORD}"
mkdir -p "$OUT"; chmod 700 "$OUT" 2>/dev/null || true

ADMIN=$(curl -sf "$KC_URL/realms/master/protocol/openid-connect/token" -d grant_type=password -d client_id=admin-cli \
  -d "username=${KC_ADMIN_USER:-admin}" --data-urlencode "password=$KC_ADMIN_PASSWORD" | sed -E 's/.*"access_token":"([^"]+)".*/\1/')

curl -sf -X POST "$KC_URL/admin/realms/$REALM/partialImport" -H "Authorization: Bearer $ADMIN" \
  -H 'Content-Type: application/json' --data-binary @"$HERE/ops-agent-partial-import.json" | sed -E 's/"(id|name)":"[^"]*"//g' >/dev/null

for c in ops-alertmanager-tenant-a ops-viewer-tenant-a ops-viewer-tenant-b; do
  ID=$(curl -sf "$KC_URL/admin/realms/$REALM/clients?clientId=$c" -H "Authorization: Bearer $ADMIN" | sed -E 's/^\[\{"id":"([^"]+)".*/\1/')
  curl -sf "$KC_URL/admin/realms/$REALM/clients/$ID/client-secret" -H "Authorization: Bearer $ADMIN" \
    | sed -E 's/.*"value":"([^"]+)".*/\1/' > "$OUT/$c.secret"
  echo "client $c: secret written to $OUT/$c.secret"
done
